import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
const violet=Color(0xFFA56EFF), lime=Color(0xFFC8F169), ink=Color(0xFF101014), panel=Color(0xFF1B1A20), muted=Color(0xFFAAA6B2);
void main() async { WidgetsFlutterBinding.ensureInitialized(); await SystemChrome.setEnabledSystemUIMode(SystemUiMode.immersiveSticky); runApp(const Smth()); }
class Smth extends StatelessWidget { const Smth({super.key}); @override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,title:'SMTH OS',theme:ThemeData.dark(useMaterial3:true).copyWith(scaffoldBackgroundColor:ink,colorScheme:const ColorScheme.dark(primary:violet,secondary:lime,surface:panel)),home:const Home()); }
class Home extends StatefulWidget { const Home({super.key}); @override State<Home> createState()=>_HomeState(); }
class _HomeState extends State<Home>{
 bool ahian=false,wifi=true,bluetooth=false,notice=false;
 final lines=<String>['SMTH Terminal 1.0','Type help to see commands.'];
 final apps = <(String, IconData)>[('Files',Icons.folder_open),('Browser',Icons.language),('Terminal',Icons.terminal),('Settings',Icons.tune),('Store',Icons.grid_view),('About',Icons.blur_circular)];
 void open(String n){ if(n=='About'){showDialog(context:context,builder:(_)=>const About());return;}
 showDialog(context:context,barrierColor:Colors.black54,builder:(_)=>AppWindow(name:n,wifi:wifi,bluetooth:bluetooth,onWifi:(v)=>setState(()=>wifi=v),onBluetooth:(v)=>setState(()=>bluetooth=v),lines:lines,onCommand:(s){setState((){lines.add('> '+s);switch(s.trim().toLowerCase()){case 'help':lines.add('help  neofetch  ahian  clear  date  ls');break;case 'neofetch':lines.add('SMTH OS • visual preview • AHian '+(ahian?'on':'off'));break;case 'ahian':ahian=!ahian;lines.add('AHIAN mode toggled.');break;case 'clear':lines.clear();break;case 'date':lines.add(DateTime.now().toString());break;case 'ls':lines.add('Documents/ Downloads/ Pictures/ notes.txt');break;case '':break;default:lines.add('Command not found. Try help.');}});}));
 }
 @override Widget build(BuildContext c){final wide=MediaQuery.sizeOf(c).width>=700;return Scaffold(body:Stack(children:[Positioned.fill(child:CustomPaint(painter:Dots(ahian))),Positioned.fill(child:ColoredBox(color:(ahian?const Color(0xFF171322):ink).withOpacity(.78))),SafeArea(child:Column(children:[top(),Expanded(child:wide?desktop():mobile()),dock(wide)])),if(notice)Positioned(right:14,top:58,child:Container(width:250,padding:const EdgeInsets.all(16),decoration:BoxDecoration(color:panel,borderRadius:BorderRadius.circular(16),border:Border.all(color:violet)),child:const Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('NOTIFICATIONS',style:TextStyle(color:lime,fontSize:10,letterSpacing:2)),SizedBox(height:14),Text('You’re all caught up.'),Text('SMTH preview is running.',style:TextStyle(color:muted,fontSize:12))])))]));}
