 Widget desktop()=>Padding(padding:const EdgeInsets.all(28),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Spacer(),Text(ahian?'AHIAN MODE':'A DIFFERENT KIND OF DESKTOP',style:const TextStyle(color:lime,fontSize:11,letterSpacing:2.4,fontWeight:FontWeight.bold)),const SizedBox(height:10),const Text('Make space\\nfor what matters.',style:TextStyle(fontSize:46,height:1.02,fontWeight:FontWeight.w800,letterSpacing:-2)),const SizedBox(height:12),const Text('A lightweight desktop concept by SMTH.',style:TextStyle(color:muted)),const SizedBox(height:35),Wrap(spacing:12,runSpacing:12,children:apps.map((a)=>tile(a.$1,a.$2)).toList()),const Spacer()]));
 Widget mobile()=>Padding(padding:const EdgeInsets.fromLTRB(22,30,22,16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Spacer(),const Text('SMTH',style:TextStyle(fontSize:48,fontWeight:FontWeight.w900,letterSpacing:7)),Text(ahian?'AHIAN MODE':'LESS NOISE. MORE YOU.',style:const TextStyle(color:lime,letterSpacing:2,fontSize:11)),const Spacer(),const Text('Your space',style:TextStyle(fontSize:20,fontWeight:FontWeight.bold)),const SizedBox(height:15),Expanded(flex:3,child:GridView.count(crossAxisCount:3,mainAxisSpacing:16,crossAxisSpacing:10,children:apps.map((a)=>tile(a.$1,a.$2)).toList()))]));
