}
class Dots extends CustomPainter{final bool alt;Dots(this.alt);@override void paint(Canvas c,Size s){final p=Paint()..color=(alt?lime:violet).withOpacity(.3);for(double y=18;y<s.height;y+=22){for(double x=18;x<s.width;x+=22){final dx=x-s.width*.78,dy=y-s.height*.38;if(dx*dx+dy*dy>17000)c.drawCircle(Offset(x,y),1.15,p);}}}@override bool shouldRepaint(covariant Dots o)=>o.alt!=alt;}
class AppWindow extends StatefulWidget{final String name;final bool wifi,bluetooth;final ValueChanged<bool> onWifi,onBluetooth;final List<String> lines;final ValueChanged<String> onCommand;const AppWindow({super.key,required this.name,required this.wifi,required this.bluetooth,required this.onWifi,required this.onBluetooth,required this.lines,required this.onCommand});@override State<AppWindow> createState()=>_AppWindowState();}
class _AppWindowState extends State<AppWindow>{final input=TextEditingController();@override void dispose(){input.dispose();super.dispose();}
 @override Widget build(BuildContext c)=>Dialog(backgroundColor:panel,insetPadding:const EdgeInsets.all(18),shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(18),side:const BorderSide(color:violet)),child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:620,maxHeight:620),child:Column(mainAxisSize:MainAxisSize.min,children:[Container(padding:const EdgeInsets.symmetric(horizontal:16,vertical:10),decoration:const BoxDecoration(border:Border(bottom:BorderSide(color:Colors.white12))),child:Row(children:[Icon(icon,color:lime),const SizedBox(width:10),Text(widget.name.toUpperCase(),style:const TextStyle(letterSpacing:1.5,fontWeight:FontWeight.bold,fontSize:12)),const Spacer(),IconButton(onPressed:()=>Navigator.pop(c),icon:const Icon(Icons.close))])),Flexible(child:SingleChildScrollView(padding:const EdgeInsets.all(18),child:content()))])));
 IconData get icon=>switch(widget.name){'Files'=>Icons.folder_open,'Browser'=>Icons.language,'Terminal'=>Icons.terminal,'Settings'=>Icons.tune,_=>Icons.grid_view};
 Widget content(){switch(widget.name){
 case 'Files':return Column(children:[const Align(alignment:Alignment.centerLeft,child:Text('HOME / USER',style:TextStyle(color:muted,fontSize:10,letterSpacing:1.5))),...['Documents','Downloads','Pictures','Music','Videos','notes.txt'].map((s)=>ListTile(dense:true,leading:Icon(s.endsWith('.txt')?Icons.description:Icons.folder_outlined,color:violet),title:Text(s),trailing:const Icon(Icons.more_horiz,color:muted))),const Text('Demo file browser • changes are not saved',style:TextStyle(color:muted,fontSize:11))]);
 case 'Browser':return const Column(children:[Icon(Icons.blur_circular,color:violet,size:55),SizedBox(height:12),Text('Welcome to SMTH Web',style:TextStyle(fontSize:20,fontWeight:FontWeight.bold)),SizedBox(height:8),Text('A visual browser preview. External browsing is not connected yet.',textAlign:TextAlign.center,style:TextStyle(color:muted))]);
 case 'Terminal':return Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[Container(padding:const EdgeInsets.all(12),decoration:BoxDecoration(color:ink,borderRadius:BorderRadius.circular(12)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[...widget.lines.map((l)=>Padding(padding:const EdgeInsets.only(bottom:5),child:Text(l,style:const TextStyle(fontFamily:'monospace',fontSize:12,color:lime)))),Row(children:[const Text('smth > ',style:TextStyle(color:violet,fontFamily:'monospace')),Expanded(child:TextField(controller:input,style:const TextStyle(fontFamily:'monospace',fontSize:12),decoration:const InputDecoration(isDense:true,border:InputBorder.none,hintText:'enter command'),onSubmitted:(v){widget.onCommand(v);input.clear();setState((){});} ))])])),const SizedBox(height:10),const Text('Try: help, neofetch, ahian, date, ls, clear',style:TextStyle(color:muted,fontSize:11))]);
 case 'Settings':return Column(children:[SwitchListTile(value:widget.wifi,onChanged:widget.onWifi,activeColor:lime,secondary:const Icon(Icons.wifi,color:violet),title:const Text('Wi-Fi'),subtitle:const Text('Preview toggle')),SwitchListTile(value:widget.bluetooth,onChanged:widget.onBluetooth,activeColor:lime,secondary:const Icon(Icons.bluetooth,color:violet),title:const Text('Bluetooth'),subtitle:const Text('Preview toggle')),const Divider(color:Colors.white12),const ListTile(leading:Icon(Icons.palette_outlined,color:violet),title:Text('Appearance'),subtitle:Text('Electric Violet • Acid Lime')),const ListTile(leading:Icon(Icons.memory,color:violet),title:Text('System'),subtitle:Text('SMTH Launcher Preview'))]);
 default:return Column(children:[const Text('SMTH STORE',style:TextStyle(color:lime,letterSpacing:2,fontWeight:FontWeight.bold)),...['Notes','Calculator','Clock','Weather'].map((s)=>ListTile(leading:const Icon(Icons.apps,color:violet),title:Text(s),trailing:const Text('COMING SOON',style:TextStyle(color:muted,fontSize:9))))]);
 }}
